// Generated adapters that make an agent-neutral Silver workspace discoverable
// to specific agent hosts. `.skills/` and `AGENTS.md` stay canonical; every
// file rendered here is disposable and regenerated by `silver repair`.
import { lstat, readlink } from "node:fs/promises";
import path from "node:path";
import { createWorkspaceMutator } from "../framework/runtime/workspace-mutations.mjs";
import { fileURLToPath } from "node:url";

import { exists, readUtf8 } from "./lib/files.mjs";
import { nativeExecutablePath } from "./payload.mjs";
import { PACKAGE_SPEC } from "./version.mjs";
import { WORKSPACE_PRACTICE_OVERLAY_PATH } from "./practice-overlay.mjs";

const installerRoot = path.dirname(fileURLToPath(import.meta.url));

export const CLAUDE_BLOCK_BEGIN =
  "<!-- silver:begin — generated by The Silver Design Framework. Run `silver repair` to regenerate. -->";
export const CLAUDE_BLOCK_END = "<!-- silver:end -->";

export const LAUNCHER_PATH = ".silver/bin/silver";
export const LAUNCHER_CMD_PATH = ".silver/bin/silver.cmd";
export const CLAUDE_MEMORY_PATH = "CLAUDE.md";
export const CLAUDE_SKILLS_DIRECTORY = ".claude/skills";

// Absolute path to the bin/silver.mjs of the Silver installation running now.
export function silverEntryPoint() {
  return nativeExecutablePath() ?? path.resolve(installerRoot, "..", "bin", "silver.mjs");
}

function isNativeEntryPoint(entryPoint) {
  const native = nativeExecutablePath();
  return native !== null && path.resolve(entryPoint) === native;
}

// npx unpacks into a cache npm garbage-collects, so an absolute path into it
// rots. Resolve through npx by version instead when that is where we are.
export function isEphemeralInstall(entryPoint = silverEntryPoint()) {
  return entryPoint.split(path.sep).includes("_npx");
}

// Where a workspace's own npm install puts the CLI, relative to the launcher at
// `.silver/bin/silver`.
const WORKSPACE_RELATIVE_CLI =
  "node_modules/silver-design-framework/bin/silver.mjs";

// True when the CLI generating this workspace is the copy installed *into* this
// workspace. That is the npm case, and it needs no absolute path at all.
function isWorkspaceInstall(root, entryPoint) {
  const expected = path.resolve(
    path.resolve(root),
    ...WORKSPACE_RELATIVE_CLI.split("/"),
  );
  return path.resolve(entryPoint) === expected;
}

// A durable path outside the workspace — a source checkout, an `npm link`, or a
// global install. Recording it keeps those workflows working, but it is only
// ever a fallback after the portable probe, never the primary resolution.
function durableFallback(root, entryPoint) {
  if (isEphemeralInstall(entryPoint)) return null;
  if (isWorkspaceInstall(root, entryPoint)) return null;
  return entryPoint;
}

export function renderLauncher(root, entryPoint = silverEntryPoint()) {
  const fallback = durableFallback(root, entryPoint);
  const nativeFallback = fallback && isNativeEntryPoint(fallback);
  return [
    "#!/bin/sh",
    "# Generated by The Silver Design Framework. Run `silver repair` to regenerate.",
    "# Indirection so the workspace never hard-codes how the CLI is delivered.",
    "# Resolution is relative to this file, so the workspace stays portable across",
    "# machines, checkouts, users, and operating systems.",
    'here=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)',
    'root=$(CDPATH= cd -- "$here/../.." && pwd)',
    `workspace_cli="$root/${WORKSPACE_RELATIVE_CLI}"`,
    'if [ -f "$workspace_cli" ]; then',
    '  exec node "$workspace_cli" "$@"',
    "fi",
    ...(fallback
      ? [
          "# silver:fallback — the installation that generated this workspace.",
          `if [ ${nativeFallback ? "-x" : "-f"} ${shellQuote(fallback)} ]; then`,
          nativeFallback
            ? `  exec ${shellQuote(fallback)} "$@"`
            : `  exec node ${shellQuote(fallback)} "$@"`,
          "fi",
        ]
      : []),
    "# The exact published version this workspace was created with. It stays",
    "# resolvable after npm prunes its cache, and npm verifies integrity on fetch.",
    `exec npx --yes ${PACKAGE_SPEC} "$@"`,
    "",
  ].join("\n");
}

export function renderLauncherCmd(root, entryPoint = silverEntryPoint()) {
  // A POSIX fallback path is meaningless on Windows, and writing one is how a
  // macOS-generated .cmd ended up carrying a macOS path. Only record a fallback
  // when it was produced on the platform that can use it.
  const fallback =
    path.sep === "\\" ? durableFallback(root, entryPoint) : null;
  const relative = `%~dp0..\\..\\${WORKSPACE_RELATIVE_CLI.split("/").join("\\")}`;
  return [
    "@echo off",
    "REM Generated by The Silver Design Framework. Run `silver repair` to regenerate.",
    "REM Resolution is relative to this file, so the workspace stays portable.",
    `if exist "${relative}" (`,
    `  node "${relative}" %*`,
    "  exit /b %ERRORLEVEL%",
    ")",
    ...(fallback
      ? [
          "REM silver:fallback — the installation that generated this workspace.",
          `if exist "${fallback}" (`,
          `  node "${fallback}" %*`,
          "  exit /b %ERRORLEVEL%",
          ")",
        ]
      : []),
    `npx --yes ${PACKAGE_SPEC} %*`,
    "",
  ].join("\r\n");
}

// Single-quote for /bin/sh, closing and reopening around any embedded quote.
function shellQuote(value) {
  return `'${value.split("'").join(`'\\''`)}'`;
}

// The Silver half of a workspace CLAUDE.md. Claude Code reads CLAUDE.md and not
// AGENTS.md, so this imports AGENTS.md rather than restating it.
export function renderClaudeBlock(skillIds = []) {
  return [
    CLAUDE_BLOCK_BEGIN,
    "",
    "@AGENTS.md",
    "",
    "## Silver design workspace",
    "",
    "This repository is a Silver workspace. `design/manifest.yaml` and the design",
    "artifacts it maps are the sources of truth; `design/INDEX.md` is generated.",
    "",
    `Design work belongs in the ${skillIds.length} project-local skills. Read the relevant`,
    "`.skills/<id>/SKILL.md` before starting, then run the guarded operation through",
    "the workspace launcher:",
    "",
    "```sh",
    ".silver/bin/silver invoke --scaffold <skill-id> .   # emit a prefilled request",
    ".silver/bin/silver invoke <skill-id> <request.json> .",
    ".silver/bin/silver what-now .                       # rank next actions",
    ".silver/bin/silver check .                          # run the fast checks",
    ".silver/bin/silver doctor .                         # read-only diagnosis",
    "```",
    "",
    "Do not run scripts under `.skills/<id>/scripts/` directly. They need",
    "dependencies the workspace does not carry; the launcher resolves them.",
    "",
    "### Rules",
    "",
    "- Run one skill, then stop. Report what it produced and what its checks",
    "  actually said, offer two or three directions, and let the designer choose.",
    "  A request to explore is not authorization to run the whole chain.",
    "- Recommended next actions are never started automatically.",
    "- Recipes, implementation profiles, and playbooks are offered, never chosen",
    "  for the designer.",
    "- Never suspend design-system constraints unless the user explicitly asks for a",
    "  partial or suspended prototype constraint profile. A request to explore is not",
    "  a request to suspend.",
    "- Propose changes to canonical artifacts and wait for approval before writing.",
    "- Never put credentials or secrets in bindings, tool profiles, or artifacts.",
    "",
    `If \`${WORKSPACE_PRACTICE_OVERLAY_PATH}\` exists, read it. It carries the personal`,
    "practice of whoever is working here — their studio voice and their method",
    "overlays — from outside the project, and it takes precedence over the studio",
    "voice in AGENTS.md. Personal preference adds to how the work is done; it never",
    "relaxes project facts, guardrails, required guidance, or approval boundaries.",
    "",
    CLAUDE_BLOCK_END,
    "",
  ].join("\n");
}

// Insert or refresh the Silver block without disturbing project-owned content.
export function mergeClaudeMemory(existing, block) {
  if (existing === undefined || existing.trim() === "") return block;
  const begin = existing.indexOf(CLAUDE_BLOCK_BEGIN);
  const end = existing.indexOf(CLAUDE_BLOCK_END);
  if (begin >= 0 && end > begin) {
    const after = end + CLAUDE_BLOCK_END.length;
    return `${existing.slice(0, begin)}${block.trimEnd()}${existing.slice(after)}`;
  }
  // Silver's block goes first so `@AGENTS.md` is imported before project notes.
  return `${block}\n${existing.trimStart()}`;
}

export function claudeMemoryIsCurrent(content, block) {
  return mergeClaudeMemory(content, block) === content;
}

// Ids like `system`, `map`, and `research` are generic enough that a personal or
// bundled skill of the same name can shadow them, leaving installed Silver
// skills unreachable by their advertised names. The adapter layer is namespaced
// so the advertised name is unambiguous, while `.skills/<id>` and the contract
// id stay unchanged — handoffs, recommendations, playbooks, and
// `silver invoke <id>` all keep working.
export const ADAPTER_SKILL_PREFIX = "silver-";

export function adapterSkillName(id) {
  return `${ADAPTER_SKILL_PREFIX}${id}`;
}

// Link .claude/skills/silver-<id> at the canonical .skills/<id>. Claude Code
// follows symlinks in project skill directories; copying is the Windows
// fallback.
export async function writeClaudeSkillLinks(root, skillIds) {
  const mutator = await createWorkspaceMutator(root);
  const workspaceRoot = mutator.root;
  const skillsRoot = path.join(workspaceRoot, CLAUDE_SKILLS_DIRECTORY);
  await mutator.ensureDirectory(CLAUDE_SKILLS_DIRECTORY);
  const linked = [];
  let mode = "symlink";
  for (const id of skillIds) {
    // Remove any un-namespaced link a pre-0.7 workspace left behind.
    await mutator.remove(path.posix.join(CLAUDE_SKILLS_DIRECTORY, id), {
      force: true,
      recursive: true,
      allowLeafLink: true,
    });
    const linkPath = path.join(skillsRoot, adapterSkillName(id));
    const target = path.posix.join("..", "..", ".skills", id);
    const current = await currentLinkTarget(linkPath);
    if (current === target) continue;
    await mutator.remove(
      path.posix.join(CLAUDE_SKILLS_DIRECTORY, adapterSkillName(id)),
      { force: true, recursive: true, allowLeafLink: true },
    );
    try {
      await mutator.managedSkillLink(
        path.posix.join(CLAUDE_SKILLS_DIRECTORY, adapterSkillName(id)),
        target,
      );
    } catch {
      mode = "copy";
      await mutator.copyTree(
        path.join(workspaceRoot, ".skills", id),
        path.posix.join(CLAUDE_SKILLS_DIRECTORY, adapterSkillName(id)),
      );
    }
    linked.push(path.posix.join(CLAUDE_SKILLS_DIRECTORY, adapterSkillName(id)));
  }
  return { mode, linked };
}

async function currentLinkTarget(linkPath) {
  try {
    const stats = await lstat(linkPath);
    if (!stats.isSymbolicLink()) return null;
    return await readlink(linkPath);
  } catch {
    return null;
  }
}

export async function claudeSkillLinkState(root, skillIds) {
  const workspaceRoot = path.resolve(root);
  const missing = [];
  const broken = [];
  for (const id of skillIds) {
    const linkPath = path.join(
      workspaceRoot,
      CLAUDE_SKILLS_DIRECTORY,
      adapterSkillName(id),
    );
    if (!(await exists(linkPath))) {
      missing.push(id);
      continue;
    }
    if (!(await exists(path.join(linkPath, "SKILL.md")))) {
      broken.push(id);
    }
  }
  return { missing, broken };
}

// Write the launcher pair and report which paths changed.
export async function writeLauncher(root, entryPoint = silverEntryPoint()) {
  const mutator = await createWorkspaceMutator(root);
  const workspaceRoot = mutator.root;
  const written = [];
  for (const [relativePath, content] of [
    [LAUNCHER_PATH, renderLauncher(workspaceRoot, entryPoint)],
    [LAUNCHER_CMD_PATH, renderLauncherCmd(workspaceRoot, entryPoint)],
  ]) {
    const absolute = path.join(workspaceRoot, relativePath);
    const current = (await exists(absolute)) ? await readUtf8(absolute) : null;
    if (current === content) continue;
    await mutator.write(relativePath, content, {
      ...(relativePath === LAUNCHER_PATH ? { mode: 0o755 } : {}),
    });
    written.push(relativePath);
  }
  return written;
}

// How a workspace launcher resolves the CLI. `null` when there is no launcher.
//
// A 0.7 launcher probes the workspace's own node_modules first and can never go
// stale, so it needs no verification. A pre-0.7 launcher hard-coded one absolute
// path with no probe and no fallback; that is the shape that rots when the
// workspace moves, and doctor still reports it so `silver repair` can replace it.
export async function launcherResolution(root) {
  const absolute = path.join(path.resolve(root), LAUNCHER_PATH);
  if (!(await exists(absolute))) return null;
  const content = await readUtf8(absolute);
  if (content.includes('workspace_cli="$root/')) {
    const fallback = /^if \[ -f '(.+)' \]; then$/m.exec(content);
    return {
      mode: "portable",
      ...(fallback ? { fallbackEntryPoint: fallback[1] } : {}),
    };
  }
  if (/^exec npx /m.test(content)) return { mode: "npx" };
  const legacy = /^exec node "(.+)" "\$@"$/m.exec(content);
  return legacy
    ? { mode: "hard-coded-path", entryPoint: legacy[1] }
    : { mode: "unknown" };
}
